 "content": "def transform(grid):
    """Shift all non-background cells down one row, clipping at the bottom."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out

